function UIFishPoolActivityTaskNode1:FillSelf(newTaskId)
    self._allData = fishingComponent:GetTaskData()
    if not self._isFirst then
        table.sort(self._allData, function(a, b)
        return checkNumber(a.order) < checkNumber(b.order)
        end)
    end
    print(table.dump(self._allData))
    self:FillTimer()
    self:FillTasks(newTaskId)
