function UIFishPoolActivityTaskNode1:FillTimer()
    CfUtils.FillText(self.TextNumber, fishingComponent:GetRemainTaskSubmitTimes())
    CfUtils.FillText(self.TextDesc2, fishingComponent:GetRemainFreeRefreshTimes().."/"..FishingUtils.GetTaskMaxRefreshNum())
end

function UIFishPoolActivityTaskNode1:FillTasks(newTaskId)
    local vo = FishingUtils.GetFishActivityPlanVo(self._activityId)

    for i = 1, #self._allData do
        local go = self.Layout.transform:Find("go"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.CardNode, self.Layout)
            go.name = "go"..i
        end

        self:FillTask(go, self._allData[i])
        CfUtils.SetActive(go, true)

        if checkNumber(self._allData[i].realTaskId) == checkNumber(newTaskId) then 
            CfUtils.PlayAnimation(go, "FishPoolActivityTaskDialog"..vo.changeId.."CardChange")
        elseif not self._isFirst then
            CfUtils.PlayAnimation(go, "FishPoolActivityTaskDialog"..vo.changeId.."CardIn")
        else
            CfUtils.PlayAnimation(go, "FishPoolActivityTaskDialog"..vo.changeId.."CardIdle")
        end
    end

    if #self._allData < self.Layout.childCount then
        for i = #self._allData + 1, self.Layout.childCount do
            local go = self.Layout.transform:Find("go"..i)
            if go then
                CfUtils.SetActive(go, false)
            end
        end
    end

    self._isFirst = true
end

function UIFishPoolActivityTaskNode1:FillTask(go, data)
    if not go or not data then
        return
    end

    local scr = CfUtils.GetLuaScr(go, "Game.UI.Fishing.UIFishPoolActivityTaskDialog.UIFishPoolActivityTaskCellNode")
    if scr then
        scr:Refresh(data, self)
    end
end

function UIFishPoolActivityTaskNode1:OnDestroy()
    GameUtils.SetRedPointNum(Constants.RedPointConst.PhoneFishActivityTask, FishingUtils.IsHaveCanSubTask() and 1 or 0)

    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

